<?php
require __DIR__.'/../app/bootstrap.php';require_admin();
$tests=$pdo->query("SELECT t.id,t.title,t.is_active,COUNT(q.id) question_count,s.name subject_name FROM tests t LEFT JOIN topics tp ON tp.id=t.topic_id LEFT JOIN subjects s ON s.id=tp.subject_id LEFT JOIN questions q ON q.test_id=t.id GROUP BY t.id ORDER BY t.created_at DESC")->fetchAll();
$attempts=$pdo->query("SELECT a.score,a.finished_at,t.title FROM attempts a JOIN tests t ON t.id=a.test_id WHERE a.finished_at IS NOT NULL ORDER BY a.finished_at DESC LIMIT 10")->fetchAll();
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beheer - Leren</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="admin.php">Leren beheer</a><div><span class="text-white me-3"><?=e($_SESSION['user']['name'])?></span><a class="btn btn-outline-light btn-sm" href="index.php">Website</a> <a class="btn btn-outline-light btn-sm" href="import.php">Importeren</a> <a class="btn btn-outline-light btn-sm" href="logout.php">Uitloggen</a></div></div></nav><main class="container py-4"><div class="d-flex justify-content-between align-items-center mb-3"><h1>Toetsen</h1><a class="btn btn-primary" href="test_edit.php">Nieuwe toets</a></div><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Toets</th><th>Vak</th><th>Vragen</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($tests as $t):?><tr><td><?=e($t['title'])?></td><td><?=e($t['subject_name'])?></td><td><?=$t['question_count']?></td><td><?=((int)$t['is_active']?'Actief':'Inactief')?></td><td><a class="btn btn-sm btn-outline-primary" href="test_edit.php?id=<?=$t['id']?>">Bewerken</a> <a class="btn btn-sm btn-outline-secondary" href="questions.php?test_id=<?=$t['id']?>">Vragen</a></td></tr><?php endforeach;?></tbody></table></div></div><h2 class="h4 mt-5">Recente resultaten</h2><div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Toets</th><th>Score</th><th>Datum</th></tr></thead><tbody><?php foreach($attempts as $a):?><tr><td><?=e($a['title'])?></td><td><?=e((string)$a['score'])?>%</td><td><?=e($a['finished_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
